#include <bits/stdc++.h>
using namespace std;

int main() {
    int N;
    cin >> N;

    vector<int> nums(N);
    for (int i = 0; i < N; i++) {
        cin >> nums[i];
    }

    int maxXor = 0;

    for (int i = 0; i < N; i++) {
        for (int j = i + 1; j < N; j++) {
            maxXor = max(maxXor, nums[i] ^ nums[j]);
        }
    }

    cout << maxXor << '\n';
    return 0;
}
